/// <summary>
/// Интерфейс метода создания ордера
/// </summary>
interface RMarketMethodInterface_CreateOrder
{
}

Method.Source:
/// <summary> Создать новый ордер </summary>
/// <param name="_symbol"> Торговый символ (например, BTCUSDT) </param>
/// <param name="_side"> Направление ордера (BUY/SELL) </param>
/// <param name="_orderType"> Тип ордера (MARKET, LIMIT и т.д.) </param>
/// <param name="_quantity"> Количество актива </param>
/// <param name="_price"> Цена актива (для лимитных ордеров) </param>
/// <param name="_clientOrderId"> Клиентский идентификатор ордера </param>
/// <returns> Результат создания ордера </returns>
public void initParameters(
    RMarketType _marketType,
    RMarketSymbolId _symbol,
    RMarketOrderSide _orderSide,
    RMarketOrderType _orderType,
    str _qty,
    str _price = '',
    str _clientOrderId = '')
{}
